@import '../../utils/forced-colors.css';
@import '../../utils/chrome-header.css';

:host {
  display: grid;
  overflow: hidden;
  min-width: 0;
  grid-template-rows: 0fr;
  transition: grid-template-rows var(--effect-animation-duration-short-3)
    var(--_banner-motion-easing);

  --ds-banner-background: var(--color-background-faint-neutral);
  --ds-banner-heading: var(--color-foreground-primary);
  --ds-banner-description: var(--color-foreground-secondary);
  --ds-banner-border: var(--color-border-tertiary);
  --_banner-motion-easing: var(--effect-animation-easing-ease-in-out, ease);
}

:host(.banner--open) {
  grid-template-rows: 1fr;
  --_banner-motion-easing: var(--effect-animation-easing-ease-out, ease-out);
}

:host(.banner--closing) {
  --_banner-motion-easing: var(--effect-animation-easing-ease-in, ease-in);
}

:host(.banner--hidden) {
  display: none;
}

.banner-overflow {
  min-height: 0;
  overflow: visible;
}

.banner-surface {
  display: flex;
  position: relative;
  width: 100%;
  padding-inline-end: calc(var(--dimension-size-400) + var(--dimension-space-200));
  color: var(--ds-banner-description);
  background-color: var(--ds-banner-background);
  border-bottom: var(--dimension-stroke-width-012) solid var(--ds-banner-border);
  transform: translateY(-100%);
  transition: transform var(--effect-animation-duration-short-3) var(--_banner-motion-easing);
}

:host(.banner--open) .banner-surface {
  transform: translateY(0);
}

.banner-copy {
  flex-basis: var(--dimension-card-width-sm);
}

:host(.banner--orientation-horizontal) .banner-surface {
  flex-wrap: nowrap;
}

:host(.banner--orientation-vertical) .banner-copy {
  flex-basis: 100%;
}

.banner-copy-flow {
  box-sizing: border-box;
  min-width: 0;
  padding-inline: var(--ds-control-label-inset, var(--dimension-space-025));
  color: var(--ds-banner-description);
}

.banner-heading {
  display: inline-block;
  width: auto;
  max-width: 100%;
  margin-inline-end: var(--dimension-space-100);
  vertical-align: baseline;
  color: var(--ds-banner-heading);
}

.banner-description {
  color: var(--ds-banner-description);
}

.banner-actions {
  display: flex;
  align-items: center;
  flex: 0 0 auto;
  flex-wrap: nowrap;
  min-width: 0;
  gap: var(--dimension-space-100);
}

.banner-actions slot {
  display: contents;
}

.banner-actions ::slotted(:not(ds-button-unfilled)),
.banner-actions ::slotted(ds-button-unfilled:nth-of-type(n + 3)) {
  display: none;
}

.banner-actions--empty {
  display: none;
}

.banner-trailing {
  align-self: flex-start;
  flex-wrap: nowrap;
}

:host(.banner--orientation-vertical:not(.banner--has-actions)) .banner-trailing {
  display: contents;
}

:host(.banner--orientation-vertical.banner--has-actions) .banner-trailing {
  margin-inline: var(--dimension-space-100) auto;
  padding-block-end: var(--dimension-space-100);
  box-sizing: border-box;
}

:host(.banner--orientation-vertical) .banner-description {
  display: block;
}

:host(.banner--orientation-vertical) .banner-heading + .banner-description {
  margin-block-start: var(--dimension-space-050);
}

.banner-close {
  flex: 0 0 auto;
}

.banner-dismiss {
  position: absolute;
  inset-block-start: var(--dimension-space-100);
  inset-inline-end: var(--dimension-space-100);
}

:host(.banner--intent-neutral) {
  --ds-banner-faint-background: var(--color-background-faint-neutral);
}

:host(.banner--intent-brand) {
  --ds-banner-faint-background: var(--color-background-faint-brand);
}

:host(.banner--intent-positive) {
  --ds-banner-faint-background: var(--color-background-faint-positive);
}

:host(.banner--intent-warning) {
  --ds-banner-faint-background: var(--color-background-faint-warning);
}

:host(.banner--intent-caution) {
  --ds-banner-faint-background: var(--color-background-faint-caution);
}

:host(.banner--intent-negative) {
  --ds-banner-faint-background: var(--color-background-faint-negative);
}

:host(.banner--contrast-faint) {
  --ds-banner-background: var(--ds-banner-faint-background);
  --ds-banner-heading: var(--color-foreground-primary);
  --ds-banner-description: var(--color-foreground-secondary);
  --ds-banner-border: var(--color-border-tertiary);
}

:host(.banner--contrast-medium) {
  --ds-banner-background: var(--color-background-medium-neutral);
  --ds-banner-heading: var(--color-foreground-on-medium-background-primary);
  --ds-banner-description: var(--color-foreground-on-medium-background-secondary);
  --ds-banner-border: var(--color-border-on-medium-background-tertiary);
}

:host(.banner--intent-brand.banner--contrast-medium) { --ds-banner-background: var(--color-background-medium-brand); }
:host(.banner--intent-positive.banner--contrast-medium) { --ds-banner-background: var(--color-background-medium-positive); }
:host(.banner--intent-warning.banner--contrast-medium) { --ds-banner-background: var(--color-background-medium-warning); }
:host(.banner--intent-caution.banner--contrast-medium) { --ds-banner-background: var(--color-background-medium-caution); }
:host(.banner--intent-negative.banner--contrast-medium) { --ds-banner-background: var(--color-background-medium-negative); }

:host(.banner--contrast-strong) {
  --ds-banner-background: var(--color-background-strong-neutral);
  --ds-banner-heading: var(--color-foreground-on-strong-background-primary);
  --ds-banner-description: var(--color-foreground-on-strong-background-secondary);
  --ds-banner-border: var(--color-border-on-strong-background-tertiary);
}

:host(.banner--intent-brand.banner--contrast-strong) { --ds-banner-background: var(--color-background-strong-brand); }
:host(.banner--intent-positive.banner--contrast-strong) { --ds-banner-background: var(--color-background-strong-positive); }
:host(.banner--intent-warning.banner--contrast-strong) { --ds-banner-background: var(--color-background-strong-warning); }
:host(.banner--intent-caution.banner--contrast-strong) { --ds-banner-background: var(--color-background-strong-caution); }
:host(.banner--intent-negative.banner--contrast-strong) { --ds-banner-background: var(--color-background-strong-negative); }

:host(.banner--contrast-bold) {
  --ds-banner-background: var(--color-background-bold-neutral);
  --ds-banner-heading: var(--color-foreground-on-bold-background-primary);
  --ds-banner-description: var(--color-foreground-on-bold-background-secondary);
  --ds-banner-border: var(--color-border-on-bold-background-tertiary);
}

:host(.banner--intent-brand.banner--contrast-bold) { --ds-banner-background: var(--color-background-bold-brand); }
:host(.banner--intent-positive.banner--contrast-bold) { --ds-banner-background: var(--color-background-bold-positive); }
:host(.banner--intent-warning.banner--contrast-bold) { --ds-banner-background: var(--color-background-bold-warning); }
:host(.banner--intent-caution.banner--contrast-bold) { --ds-banner-background: var(--color-background-bold-caution); }
:host(.banner--intent-negative.banner--contrast-bold) { --ds-banner-background: var(--color-background-bold-negative); }

@media (prefers-reduced-motion: reduce) {
  :host,
  .banner-surface {
    transition: none;
  }
}

@media (forced-colors: active) {
  .banner-surface {
    color: var(--ds-forced-color-content);
    background-color: var(--ds-forced-color-surface);
    border-bottom-color: var(--ds-forced-color-content);
  }

  .banner-heading,
  .banner-description {
    color: var(--ds-forced-color-content);
  }
}

import {
  Component,
  Element,
  Event,
  EventEmitter,
  h,
  Host,
  Prop,
  State,
  Watch,
} from '@stencil/core';
import { resolveMotionTimeMs, TOKEN_DEFAULTS } from '../../utils';

export type BannerIntent =
  | 'neutral'
  | 'brand'
  | 'positive'
  | 'warning'
  | 'caution'
  | 'negative';

export type BannerContrast = 'faint' | 'medium' | 'strong' | 'bold';
export type BannerAnnouncement = 'none' | 'polite' | 'assertive';
export type BannerOrientation = 'horizontal' | 'vertical';

type BannerPhase = 'closed' | 'open' | 'closing';

@Component({
  tag: 'ds-banner',
  styleUrl: 'Banner.css',
  scoped: true,
})
export class Banner {
  @Element() el!: HTMLElement;

  /** Required explanatory copy. */
  @Prop() description!: string;
  /** Optional visual heading rendered before the description. */
  @Prop() heading: string = '';
  /** Semantic color family. */
  @Prop({ reflect: true }) intent: BannerIntent = 'neutral';
  /** Surface fill weight. */
  @Prop({ reflect: true }) contrast: BannerContrast = 'faint';
  /** Copy and action-lane arrangement, selected by the application. */
  @Prop({ reflect: true }) orientation: BannerOrientation = 'horizontal';
  /** Controlled visibility. Keep the element mounted until dsAfterClose when unmounting. */
  @Prop({ reflect: true }) open: boolean = true;
  /** Localized accessible label for the close control. */
  @Prop() dismissLabel: string = 'Dismiss banner';
  /** Live-region urgency, independent of visual intent. */
  @Prop() announcement: BannerAnnouncement = 'none';

  /** Emitted when the close control requests dismissal. The application controls open. */
  @Event() dsClose!: EventEmitter<MouseEvent>;
  /** Emitted once after controlled exit motion and layout collapse complete. */
  @Event() dsAfterClose!: EventEmitter<void>;

  @State() private rendered = false;
  @State() private phase: BannerPhase = 'closed';
  @State() private hasActions = false;

  private loaded = false;
  private transitionTimer: ReturnType<typeof setTimeout> | null = null;
  private openFrame: number | null = null;
  private closePending = false;

  componentWillLoad() {
    this.rendered = this.open;
  }

  componentDidLoad() {
    this.loaded = true;
    this.updateActionsPresence();
    if (this.open) this.startOpen();
  }

  disconnectedCallback() {
    this.clearTransitionWork();
  }

  @Watch('open')
  onOpenChange(isOpen: boolean) {
    if (!this.loaded) return;
    if (isOpen) this.startOpen();
    else this.startClose();
  }

  private get closeMotionMs(): number {
    return resolveMotionTimeMs(
      TOKEN_DEFAULTS.motionShort3,
      TOKEN_DEFAULTS.animationDurationShort3,
    );
  }

  private clearTransitionWork() {
    if (this.transitionTimer) clearTimeout(this.transitionTimer);
    if (this.openFrame !== null) cancelAnimationFrame(this.openFrame);
    this.transitionTimer = null;
    this.openFrame = null;
  }

  private startOpen() {
    this.clearTransitionWork();
    this.closePending = false;
    this.rendered = true;
    this.phase = 'closed';
    this.openFrame = requestAnimationFrame(() => {
      this.openFrame = null;
      if (this.open) this.phase = 'open';
    });
  }

  private startClose() {
    this.clearTransitionWork();
    if (!this.rendered || this.phase === 'closed') {
      this.rendered = false;
      return;
    }

    this.closePending = true;
    this.phase = 'closing';
    const duration = this.closeMotionMs;
    if (duration <= 0) {
      this.finishClose();
      return;
    }
    this.transitionTimer = setTimeout(() => {
      this.transitionTimer = null;
      this.finishClose();
    }, duration);
  }

  private finishClose() {
    if (this.open || !this.closePending) return;
    this.closePending = false;
    this.rendered = false;
    this.phase = 'closed';
    this.dsAfterClose.emit();
  }

  private updateActionsPresence(slot?: HTMLSlotElement) {
    const actions = slot
      ? slot.assignedElements().filter(element => element.tagName === 'DS-BUTTON-UNFILLED')
      : Array.from(this.el.querySelectorAll('ds-button-unfilled[slot="actions"]'));
    this.hasActions = actions.length > 0;
  }

  private requestClose(event: CustomEvent<MouseEvent>) {
    if (!this.open || this.phase === 'closing') return;
    this.dsClose.emit(event.detail);
  }

  private get role(): 'status' | 'alert' | undefined {
    if (this.announcement === 'polite') return 'status';
    if (this.announcement === 'assertive') return 'alert';
    return undefined;
  }

  private get ariaLive(): 'polite' | 'assertive' | undefined {
    return this.announcement === 'none' ? undefined : this.announcement;
  }

  render() {
    const closing = this.phase === 'closing';
    const hostClass = {
      banner: true,
      'banner--open': this.phase === 'open',
      'banner--closing': closing,
      'banner--hidden': !this.rendered,
      'banner--has-actions': this.hasActions,
      [`banner--orientation-${this.orientation}`]: true,
      [`banner--intent-${this.intent}`]: true,
      [`banner--contrast-${this.contrast}`]: true,
    };

    return (
      <Host class={hostClass}>
        {this.rendered && (
          <div class="banner-overflow">
            <section
              class="banner-surface ds-chrome-header ds-chrome-header--wrapping"
              role={this.role}
              aria-live={this.ariaLive}
              aria-atomic={this.announcement === 'none' ? undefined : 'true'}
              aria-hidden={closing ? 'true' : undefined}
              inert={closing ? true : undefined}
              data-phase={this.phase}
            >
              {/* eslint-disable-next-line local/prefer-direct-ds-text -- The header-copy lane owns the 6px container inset separately from the inline text flow's 2px inset. */}
              <div class="banner-copy ds-chrome-header__copy ds-chrome-header__copy--wrapping ds-control--md">
                <ds-text
                  class="banner-copy-flow"
                  as="div"
                  variant="text-body-medium"
                  color="inherit"
                >
                  {this.heading && (
                    <ds-text
                      class="banner-heading"
                      as="span"
                      variant="text-title-small"
                      color="inherit"
                    >
                      {this.heading}
                    </ds-text>
                  )}
                  <span class="banner-description">{this.description}</span>
                </ds-text>
              </div>
              <div class="banner-trailing ds-chrome-header__trailing">
                <div class={{ 'banner-actions': true, 'banner-actions--empty': !this.hasActions }}>
                  <slot
                    name="actions"
                    onSlotchange={(event: Event) =>
                      this.updateActionsPresence(event.currentTarget as HTMLSlotElement)
                    }
                  />
                </div>
                <div class="banner-dismiss">
                  <ds-tooltip label={this.dismissLabel} side="bottom" size="sm">
                    <ds-button-unfilled
                      class="banner-close"
                      variant="icon"
                      icon="Cross"
                      size="md"
                      type="button"
                      background={this.contrast}
                      aria-label={this.dismissLabel}
                      hasBorder={false}
                      activeFill={false}
                      onDsClick={(event: CustomEvent<MouseEvent>) => this.requestClose(event)}
                    />
                  </ds-tooltip>
                </div>
              </div>
            </section>
          </div>
        )}
      </Host>
    );
  }
}
